// <ul>
//   <li>One</li>
//   <li>Two</li>
// </ul>

// list.childNodes.length -> 4 (two <li> elements + whitespace text nodes around/between them)
// list.children.length   -> 2 (only the two <li> elements)

const entities = { "&lt;": "<", "&gt;": ">", "&amp;": "&" };

function decode(text) {
  return text.replace(/&lt;|&gt;|&amp;/g, (match) => entities[match]);
}

console.log(decode("5 &lt; 10 &amp; 10 &gt; 5")); // "5 < 10 & 10 > 5"

// nodeType values, defined by the DOM standard:
const nodeTypes = {
  ELEMENT_NODE: 1,
  TEXT_NODE: 3,
  COMMENT_NODE: 8
};

console.log(nodeTypes.ELEMENT_NODE); // 1
console.log(nodeTypes.TEXT_NODE); // 3

